// Counter Argument V2 draft recovery. These helpers use only V2 records.
function v2DraftStorage() {
  try { return localStorage; }
  catch { return {getItem() { throw new Error('Storage unavailable'); }, setItem() { throw new Error('Storage unavailable'); }, removeItem() {}}; }
}

function v2SoloDraftKey(owner, debateId) {
  return 'counter-argument-v2:solo-draft:v1:' + JSON.stringify([owner, debateId]);
}

function v2ValidateSoloDraft(value, owner, debateId) {
  const text = (input, max) => typeof input === 'string' && input.length <= max;
  if (!value || value.version !== 1 || !owner || !debateId || value.owner !== owner || value.debateId !== debateId ||
      !text(value.topic, 2000) || !value.topic.trim() || !['preparation', 'arguments'].includes(value.phase) ||
      ![null, 'for', 'against'].includes(value.humanPosition) || !Array.isArray(value.positions) || value.positions.length !== 2 ||
      !value.positions.every(position => text(position, 2000)) || !Array.isArray(value.submitted) || value.submitted.length > 10 ||
      !value.submitted.every(row => row && text(row.title, 5000) && row.title.trim() && text(row.description, 30000) && row.description.trim() && text(row.sourceUrl, 5000)) ||
      !['positionSubmitted', 'aiPositionSet', 'ready'].every(key => typeof value[key] === 'boolean')) return null;
  return {
    version: 1, owner, debateId, topic: value.topic, phase: value.phase,
    humanPosition: value.humanPosition, positions: [...value.positions],
    submitted: value.submitted.map(({title, description, sourceUrl}) => ({title, description, sourceUrl})),
    positionSubmitted: value.positionSubmitted, aiPositionSet: value.aiPositionSet, ready: value.ready,
  };
}

function v2ReadSoloDraft(storage, owner, debateId) {
  try {
    const raw = storage.getItem(v2SoloDraftKey(owner, debateId));
    if (!raw) return {draft: null, error: ''};
    if (raw.length > 400000) return {draft: null, error: 'The local draft is too large to restore safely.'};
    const draft = v2ValidateSoloDraft(JSON.parse(raw), owner, debateId);
    return {draft, error: draft ? '' : 'The saved local draft could not be validated.'};
  } catch {
    return {draft: null, error: 'Browser storage is unavailable or the local draft could not be read.'};
  }
}

function v2WriteSoloDraft(storage, snapshot) {
  const draft = v2ValidateSoloDraft(snapshot, snapshot.owner, snapshot.debateId);
  if (!draft) return false;
  try { storage.setItem(v2SoloDraftKey(draft.owner, draft.debateId), JSON.stringify(draft)); return true; }
  catch { return false; }
}

async function v2RecoverSoloDraft(storage, owner, debateId, readOwnership) {
  const result = v2ReadSoloDraft(storage, owner, debateId);
  if (!result.draft) return {status: result.error ? 'error' : 'missing', error: result.error};
  try {
    const {data, error} = await readOwnership(owner, debateId);
    if (error) return {status: 'error', error: 'Your draft is saved locally, but debate ownership could not be verified. Try reloading.'};
    if (!data || data.id !== debateId || data.participant_a !== owner || data.participant_b != null || data.status !== 'active') {
      return {status: 'error', error: 'This local draft does not belong to an available active AI debate.'};
    }
    return {status: 'ready', draft: result.draft, error: ''};
  } catch {
    return {status: 'error', error: 'Your draft is saved locally, but debate ownership could not be verified. Try reloading.'};
  }
}

function v2UseSoloDraft(input) {
  const scope = JSON.stringify([input.owner, input.debateId, !!input.enabled]);
  const [recovery, setRecovery] = p.useState({scope: '', status: 'loading', error: '', notice: ''});
  const serverSaved = !!input.workflow && input.workflow.debate_id === input.debateId && input.workflow.user_id === input.owner;
  const live = p.useRef({scope, serverSaved});
  live.current = {scope, serverSaved};
  const restored = recovery.scope === scope && recovery.status === 'ready';
  p.useEffect(() => {
    let current = true;
    const set = value => { if (current && live.current.scope === scope) setRecovery({scope, notice: '', error: '', ...value}); };
    if (!input.enabled || !input.owner || !input.debateId) return () => { current = false; };
    if (serverSaved) {
      try { v2DraftStorage().removeItem(v2SoloDraftKey(input.owner, input.debateId)); } catch {}
      set({status: 'server'});
      return () => { current = false; };
    }
    if (input.createdHere) { set({status: 'ready'}); return () => { current = false; }; }
    if (input.loading) return () => { current = false; };
    if (input.error) { set({status: 'error', error: input.error}); return () => { current = false; }; }
    set({status: 'loading'});
    v2RecoverSoloDraft(v2DraftStorage(), input.owner, input.debateId, (owner, debateId) =>
      $.from('debates').select('id,participant_a,participant_b,status').eq('id', debateId).eq('participant_a', owner).maybeSingle()
    ).then(result => {
      if (!current || live.current.scope !== scope || live.current.serverSaved) return;
      if (result.status === 'ready') input.onRestore(result.draft);
      set(result);
    });
    return () => { current = false; };
  }, [scope, input.loading, input.error, input.createdHere, serverSaved]);
  p.useEffect(() => {
    if (!input.enabled || !input.owner || !input.debateId || serverSaved || !restored || (input.loading && !input.createdHere)) return;
    const saved = v2WriteSoloDraft(v2DraftStorage(), {
      version: 1, owner: input.owner, debateId: input.debateId, topic: input.topic,
      phase: input.phase === 'preparation' ? 'preparation' : 'arguments',
      humanPosition: input.humanPosition, positions: input.positions, submitted: input.submitted,
      positionSubmitted: input.positionSubmitted, aiPositionSet: input.aiPositionSet, ready: input.ready,
    });
    if (!saved) setRecovery(value => value.scope === scope ? {...value, notice: 'Browser storage is unavailable. Keep this page open until your final submission is saved.'} : value);
  }, [scope, restored, serverSaved, input.loading, input.topic, input.phase, input.humanPosition,
      input.positions[0], input.positions[1], input.submitted, input.positionSubmitted, input.aiPositionSet, input.ready]);
  return {
    ready: restored,
    loading: !!input.enabled && !!input.owner && !!input.debateId && !serverSaved &&
      (recovery.scope !== scope || recovery.status === 'loading'),
    error: recovery.scope === scope ? recovery.error : '',
    notice: recovery.scope === scope ? recovery.notice : '',
  };
}

